-- Pesquisa externa inicial (feita em 2026-10-11) e alerta de data importante sem conteúdo.
-- Cada nota cita a fonte, a data de acesso e o nível de confiança. São referências para decidir, NÃO aconselhamento jurídico:
-- confira com o responsável técnico/jurídico da farmácia antes de aplicar.

alter table notification_events drop constraint notification_events_type_check;
alter table notification_events add constraint notification_events_type_check
  check (type in ('post_overdue', 'post_no_owner', 'approval_stale', 'campaign_unconfirmed', 'final_missing', 'integration_stale', 'collect_failed', 'target_pace', 'publish_due', 'date_uncovered'));

insert into research_notes (kind, title, summary, source_name, source_url, accessed_on, confidence, tags) values
('preco', 'PMC: o teto de preço ao consumidor da CMED',
 'A lista oficial da CMED traz o Preço Fábrica (PF) e o Preço Máximo ao Consumidor (PMC), este último "o preço a ser praticado pelo comércio varejista de medicamentos, ou seja, farmácias e drogarias". O PMC varia conforme a alíquota de ICMS da loja (colunas PMC 0%, 12%, 17%, 17,5%, 18%… 23%). Para medicamentos LIBERADOS só o PF é liberado, e o PMC deve atender às margens do art. 4º da Resolução CMED nº 1/2019. O sistema usa o PMC da alíquota cadastrada na filial para conferir ofertas.',
 'Lista de preços CMED (cabeçalho do arquivo, publicada em 09/10/2026)', 'https://www.gov.br/anvisa/pt-br/assuntos/medicamentos/cmed/precos', '2026-10-11', 'alta', array['cmed', 'pmc', 'oferta', 'preco']),
('preco', 'Vender ou ofertar acima do preço máximo é infração apurada pela CMED',
 'A CMED publica decisões de processos sancionadores contra farmácias, drogarias e distribuidoras por praticar preço acima do máximo aplicável (PMC no varejo). Ofertar acima do teto também é tratado como infração. Por isso o sistema bloqueia a conversão de uma solicitação de oferta quando o preço informado, para um item identificado por EAN, ultrapassa o PMC da alíquota de ICMS da filial. Confiança média: conclusão a partir das decisões publicadas; a penalidade exata depende do caso.',
 'CMED/Anvisa — processos sancionadores (exemplo de decisão publicada)', 'https://www.gov.br/anvisa/pt-br/assuntos/medicamentos/cmed/consulta-processos/processos-sancionadores-1/SEI25351.829569_202486.pdf', '2026-10-11', 'media', array['cmed', 'infracao', 'oferta']),
('regra', 'RDC 96/2008, art. 8º: o que é vedado na propaganda de medicamentos',
 'É vedado: estimular o uso indiscriminado; sugerir ou estimular diagnósticos ao público; incluir imagens de pessoas usando o medicamento; anunciar como novo depois de 2 anos da comercialização; incluir selos de instituições, entidades ou certificações; sugerir sabor agradável ("saboroso", "gostoso"); empregar imperativos que induzam ao consumo ("tenha", "tome", "use", "experimente"); criar expectativa de venda; divulgar como genérico o que não é; e sugerir que a saúde pode ser afetada por não usar o medicamento. O sistema confere textos de conteúdo contra esses pontos (apoio, não substitui o responsável técnico).',
 'Anvisa — Resolução RDC nº 96/2008 (Biblioteca Virtual em Saúde)', 'https://bvsms.saude.gov.br/bvs/saudelegis/anvisa/2008/res0096_17_12_2008.html', '2026-10-11', 'alta', array['rdc96', 'publicidade', 'medicamentos', 'conformidade']),
('regra', 'RDC 96/2008, arts. 26 e 27: isentos de prescrição e venda sob prescrição',
 'Para medicamentos isentos de prescrição é vedado: usar "demonstrado em ensaios clínicos" ou "comprovado cientificamente"; sugerir que o medicamento é a única alternativa, tornando supérfluos hábitos saudáveis e a consulta médica; usar nome, imagem ou voz de celebridade recomendando ou afirmando usar; e relacionar o uso a excessos etílicos ou gastronômicos. A propaganda de medicamentos de venda sob prescrição fica restrita a meios destinados exclusivamente a profissionais de saúde habilitados — não pode ir para redes sociais abertas.',
 'Anvisa — Resolução RDC nº 96/2008', 'https://bvsms.saude.gov.br/bvs/saudelegis/anvisa/2008/res0096_17_12_2008.html', '2026-10-11', 'alta', array['rdc96', 'otc', 'prescricao', 'conformidade']),
('regra', 'RDC 96/2008, arts. 10, 11, 18 e 19: o que vale para farmácias e drogarias',
 'Programas de fidelização de farmácias não podem ter medicamentos como objeto de pontuação, troca, sorteios ou prêmios, e o material do programa deve informar essa restrição (art. 10). Comparação de preços ao consumidor só entre medicamentos intercambiáveis; ao informar percentual de desconto ou preço promocional, o preço integral praticado também deve ser informado, e deve haver lista dos medicamentos anunciados com preço reduzido em local visível (art. 11 §§ 4º e 5º). Preços informados ao público devem ser em listas com nome comercial, substância, apresentação, registro, detentor e preço (art. 18). Frases de desconto por grupo ("genéricos com 30% de desconto") não podem vir com outros argumentos publicitários (art. 19).',
 'Anvisa — Resolução RDC nº 96/2008', 'https://bvsms.saude.gov.br/bvs/saudelegis/anvisa/2008/res0096_17_12_2008.html', '2026-10-11', 'alta', array['rdc96', 'farmacia', 'desconto', 'fidelidade']),
('sazonalidade', 'Dengue: janeiro a maio concentra mais de 70% dos casos',
 'Revisão epidemiológica de 10 anos aponta que a dengue tem padrão sazonal no Brasil, com maior incidência entre janeiro e maio (mais de 70% dos casos do ano), associada a calor e chuva. Útil para planejar conteúdo educativo e de produtos relacionados (repelentes, hidratação, sintomas e quando procurar atendimento) a partir do fim da primavera. O padrão varia por região e por ano.',
 'Brazilian Journal of Implantology and Health Sciences — Sazonalidade na incidência da dengue no Brasil nos últimos 10 anos', 'https://bjihs.emnuvens.com.br/bjihs/article/view/5386', '2026-10-11', 'media', array['dengue', 'sazonalidade', 'conteudo']),
('sazonalidade', 'Vírus respiratórios: período sazonal de março a agosto',
 'O boletim InfoGripe (Fiocruz), noticiado pela Agência Gov, descreve o aumento de casos de SRAG como parte do período sazonal de maior circulação de vírus respiratórios (influenza A e vírus sincicial respiratório), entre março e agosto, com variação regional (Norte/Nordeste antecipam; Centro-Sul avança depois). Útil para planejar conteúdo de prevenção, vacinação e sintomas no outono e inverno.',
 'Agência Gov — InfoGripe alerta para aumento de SRAG (boletim Fiocruz)', 'https://agenciagov.ebc.com.br/noticias/202504/infogripe-alerta-para-aumento-de-srag-em-quase-todas-as-regioes-do-pais', '2026-10-11', 'media', array['gripe', 'srag', 'sazonalidade', 'conteudo']),
('mercado', 'IPCA: inflação de Saúde e de Produtos farmacêuticos (IBGE)',
 'O IBGE publica mensalmente o IPCA com abertura por grupos e subgrupos (tabela SIDRA 7060), incluindo "Saúde e cuidados pessoais" e "Produtos farmacêuticos e óticos". O sistema importa o índice geral e esses dois recortes (variação mensal e acumulada em 12 meses) para dar contexto aos preços e às metas; é inflação ao consumidor de todo o país, não o preço da sua loja.',
 'IBGE — SIDRA, tabela 7060 (IPCA)', 'https://sidra.ibge.gov.br/tabela/7060', '2026-10-11', 'alta', array['ipca', 'precos', 'contexto']),
('mercado', 'Por que o clima ficou de fora das fontes automáticas',
 'A API gratuita do Open-Meteo, a mais simples para previsão do tempo, só pode ser usada de graça para fins não comerciais (CC-BY 4.0); uso comercial exige plano pago. Como uma farmácia é uso comercial, o sistema não consome essa API sem contratar o plano. Alternativa futura: serviço pago ou dados do INMET, após avaliar termos.',
 'Open-Meteo — Termos de uso', 'https://open-meteo.com/en/terms', '2026-10-11', 'alta', array['clima', 'fontes', 'termos'])
on conflict (title) do nothing;
